(** Every representative is distinct and its certificate checks:
    the hypothesis [reps_okb reps = true] of [LinkLP.descent_of_census]. *)
Lemma cls_all_ok : reps_okb cls_all = true.
Proof. vm_compute. reflexivity. Qed.

(** The descent at link size 25 and above, conditional only on [ι(4) ≤ 27]
    and on the census being complete from size 25 up. *)
Theorem descent_25 : IotaAtMost 4 27 -> Census cls_all 25 -> LinkDescent 4 25 54.
Proof. intros Hi Hc; exact (descent_of_census Hi cls_all 25 ltac:(lia) cls_all_ok Hc). Qed.

Theorem g_four_at_most_80_of_census_25 :
  IotaAtMost 4 27 -> Census cls_all 25 -> MeetingBound 4 56 -> GAtMost 4 80.
Proof.
  intros Hi Hc Hm.
  pose proof (g_at_most_of_descent_and_meeting 4 25 54 56 (descent_25 Hi Hc) Hm) as H.
  replace (Nat.max 54 (25 - 1 + 56)) with 80 in H by reflexivity. exact H.
Qed.
